def __init__(self, filename, bbox=None, **kwargs):
    # Validate the filename/shapefile
    self._reader = reader = shapefile.Reader(filename, **kwargs)
    self._bbox = bbox
    if reader.shp is None or reader.shx is None or reader.dbf is None:
        raise ValueError("Incomplete shapefile definition "
                         "in '%s'." % filename)

    self._fields = self._reader.fields

    # Try to read the associated .prj file for CRS information
    self.crs = None
    shp_path = Path(filename)
    prj_path = shp_path.with_suffix('.prj')
    if prj_path.is_file():
        try:
            prj_wkt = prj_path.read_text(encoding='utf-8').strip()
            if prj_wkt:
                self.crs = pyproj.CRS(prj_wkt)
        except Exception:
            # If we can't parse the .prj file, leave crs as None
            pass
